import os


class Config:
    # =========================================================================
    # Global System Settings
    # =========================================================================
    SEED = 42
    N_JOBS = 12  # Utilizing available vCPUs

    # =========================================================================
    # File Paths
    # =========================================================================
    # Metadata paths (generated by the provided metadata script)
    TRAIN_METADATA_PATH = "./metadata/train_metadata.csv"
    VAL_METADATA_PATH = "./metadata/val_metadata.csv"
    TEST_METADATA_PATH = "./metadata/test_metadata.csv"

    # Raw input paths
    TRAIN_TRACKING_PATH = "./input/train_player_tracking.csv"
    TEST_TRACKING_PATH = "./input/test_player_tracking.csv"
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Output paths
    # Using ./working/idea_38/ for caching intermediate artifacts specific to this idea
    CACHE_DIR = "./working/idea_38/"
    SUBMISSION_PATH = "./working/submission.csv"

    # Ensure cache directory exists
    os.makedirs(CACHE_DIR, exist_ok=True)

    # =========================================================================
    # Feature Engineering & Gating Hyperparameters
    # =========================================================================
    # Window size: +/- 10 frames (1.0 second context window at 10Hz)
    WINDOW_SIZE = 10

    # Gating: Relaxed Quadratic Reachability Gating threshold in yards
    # Pairs with min_dist > 3.0 are discarded early
    GATING_DISTANCE = 3.0

    # Context Awareness: Number of nearest neighbors to project onto dynamic basis
    N_NEIGHBORS = 3

    # Sentinel value for Ground 'distance' to allow tree splits to isolate modality
    GROUND_DISTANCE_SENTINEL = -1.0

    # =========================================================================
    # Training Strategy Hyperparameters
    # =========================================================================
    # Ratio of random easy negatives (anchors) to positives in the Expert dataset
    ANCHOR_RATIO = 1.0

    # Hard Negative Mining threshold (probability union > 0.05)
    HARD_NEGATIVE_THRESHOLD = 0.05

    # =========================================================================
    # Model Configurations (Dual-Model Expert Tier)
    # =========================================================================

    # 1. LightGBM Configuration (Leaf-wise growth)
    # Optimized for dense numerical data and high capacity
    LGBM_PARAMS = {
        "objective": "binary",
        "metric": "binary_logloss",
        "boosting_type": "gbdt",
        "learning_rate": 0.05,
        "num_leaves": 256,  # Deep trees for high information density
        "max_depth": 10,  # Constrained depth to prevent uncontrolled overfitting
        "feature_fraction": 0.8,
        "bagging_fraction": 0.8,
        "bagging_freq": 5,
        "is_unbalance": True,  # Handle class imbalance internally
        "verbosity": -1,
        "n_jobs": N_JOBS,
        "seed": SEED,
        "n_estimators": 2000,  # Upper bound, controlled by early stopping
    }

    # 2. XGBoost Configuration (Level-wise growth)
    # Provides structural diversity from LightGBM
    XGB_PARAMS = {
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "grow_policy": "depthwise",  # Level-wise growth
        "learning_rate": 0.05,
        "max_depth": 10,  # Deep trees
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        # scale_pos_weight will be set dynamically during training based on ratio
        "verbosity": 0,
        "n_jobs": N_JOBS,
        "random_state": SEED,
        "n_estimators": 2000,  # Upper bound, controlled by early stopping
    }

    # Training loop settings
    EARLY_STOPPING_ROUNDS = 50
    VERBOSE_EVAL = 50
